public class Views {
    public interface Public { }
    public interface Internal extends Public { }
}

public class Order {
    @JsonView(Views.Public.class)   public int id;
    @JsonView(Views.Public.class)   public String reference;
    @JsonView(Views.Internal.class) public String internalNotes;
}

ObjectMapper m = new ObjectMapper()
    .disable(MapperFeature.DEFAULT_VIEW_INCLUSION);
String json = m.writerWithView(Views.Public.class).writeValueAsString(order);

public record OrderView(int id, String reference, BigDecimal total) {
    public static OrderView from(Order o) {
        return new OrderView(o.id, o.reference, o.total);
    }
}

List<OrderView> views = orders.stream().map(OrderView::from).toList();
String json = mapper.writeValueAsString(views);

